package inventory

import (
	"reflect"
	"testing"
)

// TestLowStockWarehousesOrder 断言 issue-002 的顺序契约：
// 数量升序；数量相同时按仓库名升序。使用的都是未配置仓库（阈值 = 默认值 10），
// 因此不依赖 config/thresholds.json 的内容。
func TestLowStockWarehousesOrder(t *testing.T) {
	cases := []struct {
		name  string
		stock map[string]int
		want  []string
	}{
		{
			name:  "数量升序",
			stock: map[string]int{"wuhan": 9, "chengdu": 5, "xian": 1},
			want:  []string{"xian", "chengdu", "wuhan"},
		},
		{
			name:  "数量相同按仓库名升序",
			stock: map[string]int{"wuhan": 3, "chengdu": 3, "xian": 3},
			want:  []string{"chengdu", "wuhan", "xian"},
		},
		{
			name:  "数量与仓库名交叉",
			stock: map[string]int{"wuhan": 2, "chengdu": 2, "xian": 7},
			want:  []string{"chengdu", "wuhan", "xian"},
		},
		{
			name:  "非低库存不参与排序",
			stock: map[string]int{"wuhan": 5, "chengdu": 50, "xian": 1},
			want:  []string{"xian", "wuhan"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := LowStockWarehouses(tc.stock); !reflect.DeepEqual(got, tc.want) {
				t.Fatalf("LowStockWarehouses(%v) = %v, 期望 %v", tc.stock, got, tc.want)
			}
		})
	}
}
```

